"""Независимые формулировки заморожены до изменения игрового цикла/сравнения моделей."""
def g(kinds,when='now',target='',condition=''):
    return {'kinds':kinds.split('/'),'when':when,'target_any':target.split('|') if target else [],'condition_any':condition.split('|') if condition else []}
def c(i,text,*goals,clarify=False,forbid=None):return dict(id=f'n{i:02d}',text=text,goals=list(goals),clarify=clarify,forbid=forbid or [])
